function updateControl(){
 if(!map.getLayer('control'))return;
 const pairs=[];for(const f of historical.features){const ids=f.properties.regions||[];if(!ids.length)continue;const regions=ids.map(id=>state.regions.find(r=>r.id===id)).filter(Boolean),owners=[...new Set(regions.map(r=>r.owner))],own=regions.filter(r=>r.owner===state.player);let color=identity(owners.length>1?'shared':owners[0]).map;
 if(currentMapMode==='terrain')color='#9f987a';
 else if(currentMapMode==='military'){const stationed=state.armies.filter(a=>a.owner===state.player&&ids.includes(a.region)).reduce((v,a)=>v+a.men,0);color=stationed>7000?'#a74737':stationed>0?'#c99557':'#65756d'}
 else if(currentMapMode==='supply'){const value=own.length?own.reduce((v,r)=>v+r.supply,0)/own.length:0;color=!own.length?'#65756d':value>=15?'#86aa83':value>=10?'#c4ab6b':'#ba6b52'}
 else if(currentMapMode==='economy'){const value=own.length?own.reduce((v,r)=>v+r.tax,0)/own.length:0;color=!own.length?'#65756d':value>=7?'#d1af60':value>=4?'#9da877':'#8c7460'}
 else if(currentMapMode==='stability'){const value=own.length?own.reduce((v,r)=>v+r.loyalty,0)/own.length:0;color=!own.length?'#65756d':value>=65?'#83a487':value>=35?'#c2aa6b':'#b36250'}
 pairs.push(f.properties.id,color)}
 map.setPaintProperty('control','fill-color',['match',['get','id'],...pairs,'#aa9c75']);map.setPaintProperty('control','fill-opacity',currentMapMode==='terrain'?.08:currentMapMode==='political'?.30:.38);
}
function renderLeaders(){leaderMarkers.forEach(m=>m.remove());leaderMarkers=[];for(const id of ['caesar','senate','egypt','parthia','armenia','numidia','mauretania']){const place=({caesar:'cisalpine',senate:'roma',egypt:'egypt',parthia:'parthia',armenia:'armenia',numidia:'numidia',mauretania:'mauretania'})[id],ids=id===state.player?state.world.leadership[id]:knownLeaders(state,state.player,id),el=document.createElement('button');el.className='leader-map-label';el.innerHTML=`${factionMark(id,'insignia')}<span><strong>${esc(n(FACTIONS[id].short))}</strong><small>${esc(ids.map(cid=>n(CHARACTER_CATALOG[cid]?.name)).filter(Boolean).join(' · ')||(lang==='zh'?'领袖未知':'Leader unknown'))}</small></span>`;el.title=lang==='zh'?'公开传闻，可能过时；点击查看':'Publicly reported, may be outdated; click to inspect';el.onclick=e=>{e.stopPropagation();showFaction(id)};leaderMarkers.push(marker(el,namedPoints[place],'bottom'))}}
