function advanceTurn(){
 const before={treasury:state.factions[state.player].treasury,food:state.factions[state.player].food,owners:Object.fromEntries(state.regions.map(r=>[r.id,r.owner])),armies:Object.fromEntries(state.armies.map(a=>[a.id,{region:a.region,move:a.move?.to}]))};
 tick(state);const changes=state.regions.filter(r=>before.owners[r.id]!==r.owner).map(r=>({name:r.name,owner:FACTIONS[r.owner].short}));const movements=state.armies.filter(a=>a.owner===state.player&&before.armies[a.id]&&before.armies[a.id].region!==a.region).map(a=>({owner:a.owner,name:a.name,to:region(state,a.region).name}));const delta={treasury:state.factions[state.player].treasury-before.treasury,food:state.factions[state.player].food-before.food};(state.turnSummaries||=[]).unshift({year:state.year,month:state.month,delta,changes,movements,events:state.log.filter(e=>e.month===state.month&&e.year===state.year).slice(0,12)});state.turnSummaries=state.turnSummaries.slice(0,24);renderArmies();
 const battles=state.log.filter(e=>e.month===state.month&&e.year===state.year&&e.en.includes('Casualties:'));
 for(const event of battles){const r=state.regions.find(x=>event.en.includes('at '+x.name[0]+'.'));if(!r||!namedPoints[r.id])continue;const icon=document.createElement('button');icon.className='battle-indicator';icon.title=lang==='zh'?'查看战斗报告':'Inspect battle report';icon.setAttribute('aria-label',icon.title);icon.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3l14 14m2-14L6 17M2 6l4-4m12 0l4 4M4 15l5 5m6 0l5-5"/></svg>';icon.onclick=e=>{e.stopPropagation();const b=state.battles?.find(x=>x.region===r.id&&x.month===state.month&&x.year===state.year&&(x.attacker.owner===state.player||x.defender.owner===state.player));if(b)showBattle(b);else inspect(lang==='zh'?'战斗报告':'Battle report',lang==='zh'?event.zh:event.en)};const m=marker(icon,namedPoints[r.id]);battleMarkers.push(m);setTimeout(()=>{m.remove();battleMarkers=battleMarkers.filter(x=>x!==m)},10000)}
 const current=state.armies.find(a=>a.id===activeArmy&&a.owner===state.player)||reportedArmies(state,state.player).find(a=>a.id===activeArmy);if(current)showArmy(current);else clearReach();renderHud();renderLeaders();if(activeFaction)showFaction(activeFaction,factionSection);else if(activeInfo?.type==='character')characterUI.show(activeInfo.id);if(state.log.length){const e=state.log[0];const actor=Object.keys(FACTIONS).find(id=>e.en.startsWith(FACTIONS[id].short[0]+' '))||state.armies.find(a=>e.en.startsWith(a.name[0]+' '))?.owner;status.innerHTML=(actor?factionMark(actor,'insignia'):'')+`<span>${esc(visibleLogText(e,lang))}</span>`;status.style.display='flex';setTimeout(()=>status.style.display='none',5000)}const summary=state.turnSummaries[0];status.innerHTML=`<span>${lang==='zh'?'本月结算':'MONTHLY SUMMARY'} · ${lang==='zh'?'国库':'Treasury'} ${delta.treasury>=0?'+':''}${delta.treasury} · ${lang==='zh'?'粮食':'Food'} ${delta.food>=0?'+':''}${delta.food}<br>${summary.movements.length} ${lang==='zh'?'支军队抵达':'armies arrived'} · ${summary.changes.length} ${lang==='zh'?'处控制权变化':'control changes'} · ${lang==='zh'?'详情见战报':'see Chronicle'}</span>`;status.style.display='flex';const battle=(state.battles||[]).some(b=>b.month===state.month&&b.year===state.year&&(b.attacker.owner===state.player||b.defender.owner===state.player));if(battle&&playing)setPlaying(false);emit('advance','',{battle});
}
