document.querySelector('#language').onclick=()=>{lang=lang==='en'?'zh':'en';localStorage.setItem('spqr-lang',lang);renderHud();renderLeaders();const u=state.armies.find(a=>a.id===activeArmy&&a.owner===state.player)||reportedArmies(state,state.player).find(a=>a.id===activeArmy);if(u)showArmy(u);else if(activeBattle)showBattle(activeBattle);else if(activeFaction)showFaction(activeFaction,factionSection);else if(activeInfo?.type==='character')characterUI.show(activeInfo.id);else if(activeInfo?.type==='city')showCity(cities.find(c=>c.name===activeInfo.name));else if(activeInfo?.type==='region')showRegion(region(state,activeInfo.id));else if(activeInfo?.type==='resources')showResource(activeInfo.id);else if(activeInfo?.type==='help')openHelp();else if(document.querySelector('.faction-directory'))factionDirectory();tutorial.refresh()};
document.querySelector('#chronicle').onclick=()=>{activeInfo=null;activeBattle=null;activeArmy=null;previewDestination='';clearReach();inspect(t('chronicle'),lang==='zh'?'最近的回合结算与事件':'Recent turn summaries and events');const summaries=(state.turnSummaries||[]).slice(0,8).map(x=>`<article class="dispatch"><strong>${x.month}/${Math.abs(x.year)} · ${lang==='zh'?'国库':'Treasury'} ${x.delta.treasury>=0?'+':''}${x.delta.treasury} · ${lang==='zh'?'粮食':'Food'} ${x.delta.food>=0?'+':''}${x.delta.food}</strong>${x.movements.filter(m=>m.owner===state.player).map(m=>`<p>${esc(n(m.name))} → ${esc(n(m.to))}</p>`).join('')}${x.changes.map(c=>`<p>${esc(n(c.name))} → ${esc(n(c.owner))}</p>`).join('')}${x.events.map(e=>`<p>${esc(visibleLogText(e,lang))}</p>`).join('')}</article>`).join('');document.querySelector('#command-detail').innerHTML=`<div class="help-list">${summaries||state.log.slice(0,12).map(e=>`<p class="dispatch">${e.month}/${Math.abs(e.year)} · ${esc(visibleLogText(e,lang))}</p>`).join('')||t('empty')}</div>`};
