document.querySelector('#capture').onclick=async()=>{const button=document.querySelector('#capture');button.disabled=true;try{if(!window.html2canvas){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://unpkg.com/html2canvas@1.4.1/dist/html2canvas.min.js';script.onload=resolve;script.onerror=reject;document.head.append(script)})}map.triggerRepaint();await new Promise(resolve=>map.once('idle',resolve));const canvas=await html2canvas(document.body,{backgroundColor:'#17262a',scale:1,useCORS:true,logging:false});const link=document.createElement('a');link.download=`spqr-map-${canvas.width}x${canvas.height}.png`;link.href=canvas.toDataURL('image/png');let preview=document.querySelector('#capture-result');if(!preview){preview=document.createElement('img');preview.id='capture-result';preview.hidden=true;document.body.append(preview)}preview.src=link.href;link.click()}catch(e){status.textContent=lang==='zh'?'截图失败，请检查网络连接。':'Screenshot failed; check the network connection.';status.style.display='block';console.warn(e)}finally{button.disabled=false}};

