function saveSlot(action){const choice=document.querySelector('#save-slot').value;if(!['1','2','3'].includes(choice))return;const key=`spqr-save-${choice}`;if(action==='save'){localStorage.setItem(key,JSON.stringify(state));status.textContent=lang==='zh'?`已保存至栏位 ${choice}`:`Saved to slot ${choice}`;status.style.display='block';return}const raw=localStorage.getItem(key);if(!raw){status.textContent=lang==='zh'?'此存档栏为空。':'This slot is empty.';status.style.display='block';return}try{const saved=upgradeSave(JSON.parse(raw));if(!['caesar','senate'].includes(saved.player))throw Error('Not a Roman campaign');setPlaying(false);tutorial.stop();state=saved;activeInfo=null;activeFaction=null;activeBattle=null;activeArmy=null;previewDestination='';clearReach();battleMarkers.forEach(m=>m.remove());battleMarkers=[];renderArmies();renderHud();inspect(lang==='zh'?'存档已读取':'Campaign loaded',lang==='zh'?'已恢复战役状态。':'Campaign state restored.');status.style.display='none'}catch(e){status.textContent=lang==='zh'?'存档无法读取。':'Could not load this save.';status.style.display='block'}}
document.querySelector('#save').onclick=()=>saveSlot('save');document.querySelector('#load').onclick=()=>saveSlot('load');

