function resourceHelp(id){
 const f=state.factions[state.player],owned=state.regions.filter(r=>r.owner===state.player),troops=state.armies.filter(a=>a.owner===state.player).reduce((x,a)=>x+a.men,0),rate={low:.65,normal:1,high:1.4}[f.tax],tax=Math.round(owned.reduce((v,r)=>v+r.tax*rate*r.loyalty/100,0)-troops/1100),grain=Math.round(owned.reduce((v,r)=>v+r.food,0)-troops/1200-owned.length*2),zh=lang==='zh';
 const info={treasury:zh?`国库 ${f.treasury}；按当前战区、忠诚度、税率和军费估计每月 ${tax>=0?'+':''}${tax}。负债会降低稳定度和士气。`:`Treasury ${f.treasury}; estimated monthly change ${tax>=0?'+':''}${tax} from owned theaters, loyalty, tax and army upkeep. Debt reduces stability and morale.`,food:zh?`粮食 ${f.food}；按当前产量、战区和兵力估计每月 ${grain>=0?'+':''}${grain}。低于20会削弱战斗力，负粮会造成损耗。`:`Food ${f.food}; estimated monthly change ${grain>=0?'+':''}${grain} from production and upkeep. Below 20 weakens combat power; negative food causes losses.`,manpower:zh?`兵源 ${f.manpower.toLocaleString()}；当前每月恢复 ${owned.length*170}。征召一支军队需要3000兵源。`:`Manpower ${f.manpower.toLocaleString()}; currently gains ${owned.length*170} per month. Raising a force costs 3,000.`,stability:zh?`稳定度 ${f.stability}%。国库或粮食为负会降低稳定度；低于60且地方忠诚低于25时，缺少守军的战区可能叛乱。`:`Stability ${f.stability}%. Debt or food shortages reduce it. Below 60, an undefended theater below 25 loyalty may rebel.`,legitimacy:zh?`合法性 ${f.legitimacy}%。向其他势力宣战会降低5点；当前版本不把它作为胜负条件。`:`Legitimacy ${f.legitimacy}%. Declaring war costs five points; it is not currently a victory condition.`};return info[id]||'';
}
function showResource(id){activeInfo={type:'resources',id};activeFaction=null;activeBattle=null;activeArmy=null;previewDestination='';clearReach();inspect(lang==='zh'?'资源与政治':'RESOURCES & POLITICS',lang==='zh'?'每月变化根据当前战区和军队估算。':'Monthly changes are estimates based on current theaters and armies.');const panel=document.querySelector('#command-detail'),zh=lang==='zh',tax=state.factions[state.player].tax;panel.innerHTML=`<div class="help-list">${['treasury','food','manpower','stability','legitimacy'].map(k=>`<p>${esc(resourceHelp(k))}</p>`).join('')}</div><p class="battle-note">${zh?'税率影响收入与地方忠诚：低税每月恢复忠诚，高税每月降低忠诚。':'Tax rates affect income and theater loyalty: low tax restores loyalty, high tax reduces it.'}</p><div class="diplomacy-actions">${['low','normal','high'].map(level=>`<button data-tax="${level}" ${tax===level?'disabled':''}>${zh?({low:'低税',normal:'标准税',high:'高税'})[level]:({low:'LOW TAX',normal:'NORMAL TAX',high:'HIGH TAX'})[level]}</button>`).join('')}</div>`;panel.querySelectorAll('[data-tax]').forEach(b=>b.onclick=()=>{if(setTax(state,state.player,b.dataset.tax)){renderHud();showResource(id)}});emit('resources')}
