const helpEntries=[
 {kind:'game',en:'Move an army',zh:'如何行军',enBody:'Select your army, choose an adjacent destination, review the route and confirm. Advance months to finish travel. Crossing by sea costs 8 treasury.',zhBody:'选择己方军队，在相邻战区中选择目的地，检查路线后确认。推进月份完成行军；海上运输需要8国库。'},
 {kind:'game',en:'Battles and morale',zh:'战斗与士气',enBody:'Battles resolve when armies meet. Strength, morale, command skill, experience, food, terrain and forts influence the result. Open the battle report to see both sides and casualties.',zhBody:'敌军遭遇时即时结算。兵力、士气、指挥、经验、粮食、地形和工事影响结果。打开战斗报告可查看双方和伤亡。'},
 {kind:'game',en:'Food and supply',zh:'粮食与补给',enBody:'Food below 20 reduces combat power; negative food causes losses. The theater supply limit is currently informational and does not impose an extra penalty.',zhBody:'粮食低于20时战斗力下降；粮食为负会造成损耗。战区补给上限目前仅供参考，不额外施加惩罚。'},
 {kind:'game',en:'Recruitment and manpower',zh:'征召与兵源',enBody:'Select a city, open Manage theater, then recruit in a theater you control. Costs: 24 treasury, 3,000 manpower and 6 food.',zhBody:'选择城市，打开管理战区，在己方战区征召。消耗24国库、3000兵源和6粮食。'},
 {kind:'game',en:'Diplomacy and control',zh:'外交与控制',enBody:'Different powers may be at war, allied or at peace. Open Factions, choose a power and use diplomacy. Official inquiries are sent by letter and take months; no reply or refusal is possible.',zhBody:'各势力可能交战、结盟或和平。点击势力并选择国家即可进行外交。直接询问需要寄信，数月后可能收到答复、拒答或没有回信。'},
 {kind:'game',en:'Provincial loyalty and unrest',zh:'地方忠诚与叛乱',enBody:'Theater loyalty affects tax income. High taxes lower it; low taxes restore it. Below 25 loyalty and 60 stability, an undefended theater may rebel.',zhBody:'战区忠诚度影响税收。高税会降低忠诚度，低税可恢复。当忠诚低于25、稳定度低于60且没有守军时，战区可能叛乱。'},
 {kind:'game',en:'Turns, saving and objectives',zh:'回合、存档与目标',enBody:'Advance one month to resolve movement, economy, sieges and AI. The Chronicle records events. Select a save slot and press Save or Load. Click an objective for guidance; it will not issue orders.',zhBody:'推进一个月以结算行军、经济、围攻与AI行动。战报记录事件；选择存档栏后点击保存或读取。点击目标可查看指引，不会自动下令。'},
 {kind:'game',en:'Commander loyalty',zh:'将领忠诚',enBody:'Individual commander loyalty is not simulated in this campaign slice. The loyalty value shown belongs to the theater.',zhBody:'当前战役片段没有单独模拟将领忠诚。界面中的忠诚度属于战区。'},
 {kind:'game',en:'Research and construction',zh:'研究与建设',enBody:'Research and construction are not implemented in this campaign slice.',zhBody:'当前战役片段尚未实现研究与建设。'},
 {kind:'history',en:'Who was Julius Caesar?',zh:'尤利乌斯·凯撒是谁？',enBody:'Julius Caesar was a Roman general and politician. In 49 BCE his crossing of the Rubicon preceded the civil war against Pompey and the Senate.',zhBody:'尤利乌斯·凯撒是罗马将领和政治人物。公元前49年，他越过卢比孔河，随后与庞培和元老院爆发内战。'},
 {kind:'history',en:'Who was Pompey?',zh:'庞培是谁？',enBody:'Gnaeus Pompeius Magnus was a Roman commander and politician who opposed Caesar during the civil war.',zhBody:'格奈乌斯·庞培是罗马将领和政治人物，在内战中与凯撒对立。'}
];
for(const c of Object.values(CHARACTER_CATALOG))helpEntries.push({kind:'history',en:c.name[0],zh:c.name[1],enBody:(HISTORICAL_BIO[Object.keys(CHARACTER_CATALOG).find(id=>CHARACTER_CATALOG[id]===c)]?.[0]||c.role[0])+' Simulated health and later events are fictional.',zhBody:(HISTORICAL_BIO[Object.keys(CHARACTER_CATALOG).find(id=>CHARACTER_CATALOG[id]===c)]?.[1]||c.role[1])+' 游戏中的健康和之后的事件属于模拟。',source:c.source});
function openHelp(){activeInfo={type:'help'};activeFaction=null;activeBattle=null;activeArmy=null;previewDestination='';clearReach();const zh=lang==='zh';inspect(zh?'游戏帮助与历史':'GAME HELP & HISTORY',zh?'选择分类或搜索；游戏规则与历史知识分开。':'Choose a category or search; gameplay and history are separate.');const target=document.querySelector('#command-detail');target.innerHTML=`<div class="diplomacy-tabs"><button id="help-game">${zh?'游戏指南':'GAMEPLAY GUIDE'}</button><button id="help-history">${zh?'历史百科':'HISTORICAL ENCYCLOPEDIA'}</button></div><input id="help-search" type="search" aria-label="${zh?'搜索帮助':'Search help'}" placeholder="${zh?'搜索帮助':'Search help'}"><div id="help-results" class="help-list"></div>`;const input=target.querySelector('#help-search'),out=target.querySelector('#help-results');let category='game';const update=()=>{const q=input.value.trim().toLowerCase();out.innerHTML=helpEntries.filter(x=>x.kind===category&&[x.en,x.zh,x.enBody,x.zhBody].some(v=>v.toLowerCase().includes(q))).map(x=>{const index=helpEntries.indexOf(x);return `<article><strong>${esc(zh?x.zh:x.en)}</strong><p>${esc(zh?x.zhBody:x.enBody)}</p>${x.kind==='game'?`<button data-help-locate="${index}">${zh?'指出相关控件':'HIGHLIGHT CONTROL'}</button>`:''}${x.source?`<a href="${esc(x.source)}" target="_blank" rel="noreferrer">${zh?'查看历史资料':'Historical source'}</a>`:''}</article>`}).join('')||`<p>${zh?'没有匹配的条目。':'No matching entries.'}</p>`;out.querySelectorAll('[data-help-locate]').forEach(b=>b.onclick=()=>{const entry=helpEntries[Number(b.dataset.helpLocate)],selector=entry.en.includes('Recruitment')?'#map [data-city="MEDIOLANUM"]':entry.en.includes('Diplomacy')?'#factions':entry.en.includes('Turns')?'#advance':entry.en.includes('Food')?'#resources-help':entry.en.includes('Battles')?'#recent-battle':entry.en.includes('Move')?'#map [data-army="xiii"]':'#help';const el=document.querySelector(selector);if(!el){b.textContent=zh?'当前控件尚未出现':'Control is not available yet';return}el.classList.add('guide-highlight');el.scrollIntoView({block:'nearest',inline:'nearest'});setTimeout(()=>el.classList.remove('guide-highlight'),5000)})};input.oninput=update;target.querySelector('#help-game').onclick=()=>{category='game';update()};target.querySelector('#help-history').onclick=()=>{category='history';update()};update()}
document.querySelector('#help').onclick=openHelp;
const tutorial=createTutorial({language:()=>lang,onMode:()=>{},onReset:(mode,faction='caesar')=>{setPlaying(false);state=newGame(faction);state.difficulty=mode;if(mode==='beginner'){state.factions[faction].treasury+=40;state.factions[faction].food+=30;state.factions[faction].manpower+=3000;state.factions[faction].stability=Math.min(100,state.factions[faction].stability+5)}activeInfo=null;activeFaction=null;activeArmy=null;activeBattle=null;previewDestination='';clearReach();battleMarkers.forEach(m=>m.remove());battleMarkers=[];renderArmies();renderHud();inspect(lang==='zh'?'选择军队':'Select a command',lang==='zh'?'点击军团或城市查看详情。':'Select an army or city to inspect it.');map.flyTo({center:[12.4,43.2],zoom:5.45})}});
